#!/usr/bin/env bash
set -Eeuo pipefail
# Self-contained launcher for the audited Phase 208 CI script.
expected=012e77b60e85874531f305aebcade30d3f7b3b9d38a8458f58942ff55eed8037
tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT
base64 --decode > "$tmp.gz" <<'PAYLOAD'

PAYLOAD
gzip -dc "$tmp.gz" > "$tmp"
rm -f "$tmp.gz"
printf '%s  %s\n' "$expected" "$tmp" | sha256sum -c -
exec bash "$tmp" "$@"
